import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

public class GoodExample {
    public static void main(String[] args) {
        // Establish a connection to the database
        Connection conn = null;
        try {
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "username", "password");
        } catch (SQLException e) {
            System.out.println("Error connecting to database: " + e.getMessage());
            return;
        }

        // Create a SQL query with user input, using a prepared statement
        String query = "SELECT * FROM users WHERE name = ?";
        try (PreparedStatement pstmt = conn.prepareStatement(query)) {
            try {
                // Set the user input as a parameter
                pstmt.setString(1, request.getParameter("name"));
                try (ResultSet rs = pstmt.executeQuery()) {
                    while (rs.next()) {
                        System.out.println(rs.getString("name"));
                    }
                }
            } catch (SQLException e) {
                System.out.println("Error executing query: " + e.getMessage());
            }
        } catch (SQLException e) {
            System.out.println("Error creating prepared statement: " + e.getMessage());
        } finally {
            if (conn != null) {
                try {
                    conn.close();
                } catch (SQLException e) {
                    System.out.println("Error closing connection: " + e.getMessage());
                }
            }
        }
    }
}
```

In the good code snippet, we use a prepared statement to separate the SQL query from the user input. This makes it much harder for an attacker to inject malicious SQL code. By using a parameterized query, we ensure that the user input is treated as data, not as part of the SQL code.

